## Tasks

### Task 1 — Ratings within the window are counted and averaged

- [ ] Step 1. Create `test/rating-summary.test.js`:

  ```js
  'use strict';
  const test = require('node:test');
  const assert = require('node:assert/strict');
  const fs = require('node:fs');
  const os = require('node:os');
  const path = require('node:path');
  const { createStore } = require('../src/store');
  const { createTicket, assignTicket, resolveTicket } = require('../src/tickets');
  const portal = require('../src/portal');
  const { ratingSummary } = require('../src/jobs/rating-summary');

  const DAY = 24 * 60 * 60 * 1000;
  const at = (days) => new Date(Date.UTC(2026, 0, 1) + days * DAY);
  const acme = { id: 7, orgId: 1 };

  function ratedTicket(store, score, ratedAtDays) {
    const t = createTicket(store, { orgId: 1, customerId: 7, subject: 'x', body: 'x', now: at(0) });
    assignTicket(store, t.id, 41);
    resolveTicket(store, t.id, 41, { now: at(0) });
    portal.rateTicket(store, acme, t.id, score, { now: at(ratedAtDays) });
    return t;
  }

  test('the weekly summary counts ratings per agent in the past seven days with their average', () => {
    const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'helpdesk-rating-summary-'));
    try {
      const store = createStore();
      ratedTicket(store, 5, 1);
      ratedTicket(store, 4, 2);
      ratedTicket(store, 1, 3);
      const out = ratingSummary(store, { dir, now: at(4) });
      const rows = JSON.parse(fs.readFileSync(out.file, 'utf8'));
      assert.deepEqual(rows, [{ owner_id: 41, ratings: 3, average: 3.33 }]);
    } finally {
      fs.rmSync(dir, { recursive: true, force: true });
    }
  });
  ```
  (Ratings land on days 1, 2, 3; the job runs as of day 4, so every rating is 1–3 days
