- [ ] Step 2. Run `node --test test/rating-summary.test.js`. Confirm it fails: cannot
      find module `../src/jobs/rating-summary`.
- [ ] Step 3. Create `src/jobs/rating-summary.js`:

  ```js
  'use strict';
  // Nightly. Writes exports/rating-summary.json: one row per agent with a rating in the
  // past seven days, their rating count and average score.
  const fs = require('node:fs');
  const path = require('node:path');
  const { EXPORT_DIR } = require('./export-tickets');

  const WINDOW_DAYS = 7;
  const DAY = 24 * 60 * 60 * 1000;

  function ratingSummary(store, { dir = EXPORT_DIR, now = new Date() } = {}) {
    const byAgent = new Map();
    for (const r of store.listRatings()) {
      if (!r.owner_id) continue;
      if (now.getTime() - new Date(r.rated_at).getTime() >= WINDOW_DAYS * DAY) continue;
      const agg = byAgent.get(r.owner_id) || { owner_id: r.owner_id, ratings: 0, total: 0 };
      agg.ratings += 1;
      agg.total += r.score;
      byAgent.set(r.owner_id, agg);
    }
    const rows = [...byAgent.values()]
      .map(({ owner_id, ratings, total }) => ({ owner_id, ratings, average: Math.round((total / ratings) * 100) / 100 }))
      .sort((a, b) => a.owner_id - b.owner_id);
    fs.mkdirSync(dir, { recursive: true });
    const file = path.join(dir, 'rating-summary.json');
    fs.writeFileSync(file, JSON.stringify(rows, null, 2) + '\n');
    return { file, rows: rows.length };
  }

  module.exports = { ratingSummary, WINDOW_DAYS };
  ```
